// Tiny stand-in for @minecraft/server: just enough for Vice Pack's main.js. Records every call, and checks block ids,
// block states, item ids and particle ids against the pack's own JSON (a misspelt id is logged as an "error").
import fs from "node:fs";
export const LOG = [];
const bad = (m) => { LOG.push(["error", m]); throw new Error(m); };
const ROOT = new URL("../../../../../", import.meta.url);
const readDir = (d) => fs.readdirSync(new URL(d, ROOT)).map((f) => JSON.parse(fs.readFileSync(new URL(d + "/" + f, ROOT))));
const BLOCKS = Object.fromEntries(readDir("Vice Pack BP/blocks").map((b) => {
  const d = b["minecraft:block"].description, states = { ...(d.states ?? {}) };
  if (d.traits?.["minecraft:placement_direction"]) states["minecraft:cardinal_direction"] = ["north", "south", "east", "west"];
  return [d.identifier, states];
}));
BLOCKS["minecraft:air"] = {};
const ITEMS = new Set(readDir("Vice Pack BP/items").map((i) => i["minecraft:item"].description.identifier));
const PARTICLES = new Set(readDir("Vice Pack RP/particles").map((p) => p.particle_effect.description.identifier));

const subs = {};
const ev = (name) => ({ subscribe: (fn) => { subs[name] = fn; return fn; } });
export function fire(name, data) { subs[name](data); return data; }
let tick = 0; const intervals = [], timeouts = [];
export const system = {
  get currentTick() { return tick; },
  runInterval(fn, n) { intervals.push({ fn, n, next: tick + n }); },
  runTimeout(fn, n = 1) { timeouts.push({ fn, at: tick + n }); },
  run(fn) { timeouts.push({ fn, at: tick + 1 }); },
  beforeEvents: { startup: ev("startup") },
};
export function advance(n) {
  for (let i = 0; i < n; i++) {
    tick++;
    for (const iv of intervals) if (tick >= iv.next) { iv.next += iv.n; iv.fn(); }
    for (const t of timeouts.splice(0)) if (tick >= t.at) t.fn(); else timeouts.push(t);
  }
}
export const EasingType = { InOutSine: "InOutSine", Linear: "Linear", OutBack: "OutBack" };
export const InputPermissionCategory = { Movement: 2 };
export class MolangVariableMap {
  setColorRGB(k, c) { for (const v of [c.red, c.green, c.blue]) if (!(v >= 0 && v <= 1)) bad("bad colour"); this[k] = c; }
  setSpeedAndDirection(k, s, d) { if (typeof s !== "number" || typeof d.x !== "number") bad("bad dir"); this[k] = { s, d }; }
}
export class ItemStack {
  constructor(typeId, amount = 1) {
    if (!typeId.startsWith("minecraft:") && !ITEMS.has(typeId)) bad("unknown item " + typeId);
    this.typeId = typeId; this.amount = amount;
  }
}
export class BlockPermutation {
  constructor(id, states) { this.type = { id }; this.states = states; }
  static resolve(id, states = {}) {
    if (!BLOCKS[id]) bad("unknown block " + id);
    const def = Object.fromEntries(Object.entries(BLOCKS[id]).map(([k, v]) => [k, v[0]]));
    let p = new BlockPermutation(id, def);
    for (const [k, v] of Object.entries(states)) p = p.withState(k, v);
    return p;
  }
  getState(k) { return this.states[k]; }
  withState(k, v) {
    if (!BLOCKS[this.type.id][k]?.includes(v)) bad(`bad state ${this.type.id} ${k}=${v}`);
    return new BlockPermutation(this.type.id, { ...this.states, [k]: v });
  }
}
// ---------------------------------------------------------------- world: a flat floor at y=63
const world_blocks = new Map();
const key = (l) => `${Math.floor(l.x)},${Math.floor(l.y)},${Math.floor(l.z)}`;
export const dimension = {
  playSound(id) { LOG.push(["sound", id]); },
  spawnParticle(id, loc) {
    if (!id.startsWith("minecraft:") && !PARTICLES.has(id)) bad("unknown particle " + id);
    for (const k of "xyz") if (!Number.isFinite(loc[k])) bad("loc"); LOG.push(["particle", id]);
  },
  spawnItem(stack, loc) { LOG.push(["drop", stack.typeId, stack.amount]); },
  getBlock(l) { return block(l); },
};
export function block(l) {
  const loc = { x: Math.floor(l.x), y: Math.floor(l.y), z: Math.floor(l.z) };
  const perm = () => world_blocks.get(key(loc)) ?? new BlockPermutation(loc.y <= 63 ? "minecraft:stone" : "minecraft:air", {});
  return {
    location: loc, dimension,
    get permutation() { return perm(); },
    get typeId() { return perm().type.id; },
    get isAir() { return perm().type.id === "minecraft:air"; },
    isLiquid: false,
    above() { return block({ ...loc, y: loc.y + 1 }); },
    setPermutation(p) { world_blocks.set(key(loc), p); LOG.push(["set", p.type.id, JSON.stringify(p.states)]); },
    setType(id) { this.setPermutation(BlockPermutation.resolve(id)); },
  };
}
// ---------------------------------------------------------------- the player
const EFFECTS = new Set(["speed","slowness","haste","mining_fatigue","strength","jump_boost","nausea","regeneration","resistance","fire_resistance","blindness","night_vision","hunger","weakness","poison","wither","slow_falling","darkness"]);
const slots = new Array(36).fill(undefined);
export const player = {
  id: "-1", typeId: "minecraft:player", isValid: true, isOnGround: true, isSneaking: false, selectedSlotIndex: 0,
  mode: "Survival",
  location: { x: 0.5, y: 64, z: 0.5 }, dimension,
  getGameMode() { return this.mode; },
  getRotation() { return { x: 20, y: 135 }; },
  getHeadLocation() { return { x: 0.5, y: 65.6, z: 0.5 }; },
  getViewDirection() { return { x: 0, y: 0, z: 1 }; },
  getComponent(id) {
    if (id !== "minecraft:inventory") return undefined;
    return { container: { size: 36, getItem: (i) => slots[i], setItem: (i, it) => { slots[i] = it; } } };
  },
  addEffect(id, ticks, o) { if (!EFFECTS.has(id)) bad("bad effect " + id); if (!Number.isInteger(ticks)) bad("ticks"); LOG.push(["effect", id, ticks, o.amplifier]); },
  sendMessage(m) { LOG.push(["msg", m]); },
  runCommand(c) { LOG.push(["cmd", c]); },
  applyKnockback(h, v) { LOG.push(["knock", h, v]); },
  camera: {
    fade(o) { for (const k of ["red","green","blue"]) if (!(o.fadeColor[k] >= 0 && o.fadeColor[k] <= 1)) bad("fade colour"); LOG.push(["fade", o]); },
    setCamera(preset, o) { if (preset !== "minecraft:free" || !o.location || !o.rotation) bad("camera"); LOG.push(["camera", o.easeOptions.easeType]); },
    clear() { LOG.push(["camera", "clear"]); },
  },
  inputPermissions: { setPermissionCategory(c, on) { LOG.push(["input", c, on]); } },
  onScreenDisplay: { setActionBar(t) { LOG.push(["bar", t]); } },
};
export const inv = slots;
export const world = {
  afterEvents: { itemCompleteUse: ev("use"), entityDie: ev("die"), playerLeave: ev("leave"), playerBreakBlock: ev("break"), playerSpawn: ev("spawn") },
  beforeEvents: { playerInteractWithBlock: ev("interact"), itemUse: ev("itemUse") },
  getAllPlayers: () => [player],
};
